validator:
function validate(input) {
  const [{ Events = [] }] = input;
  const seen = new Set();
  for (const [business, type, occurrences] of Events) {
    if (business === null || type === null) return 'Every event row needs a business_id and an event_type.';
    if (occurrences === null) return 'occurrences is never null.';
    const key = `${business}/${String(type).toLowerCase()}`;
    if (seen.has(key)) return `Business ${business} has event type '${type}' twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const types = small ? ['reviews', 'ads', 'page views', 'clicks'] : ['reviews', 'ads', 'page views', 'clicks', 'shares'];
  const businesses = small ? 1 + Math.floor(rand() * 4) : 500;
  const pairs = [];
  for (let b = 1; b <= businesses; b++) for (const type of types) pairs.push([b, type]);
  // Shuffle the (business, type) pairs and keep a prefix, so the key stays unique.
  for (let i = pairs.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Each type gets its own scale, so the per-type average differs from the overall one; small values make ties with the average likely.
  const scale = Object.fromEntries(types.map((type, i) => [type, small ? 1 + i * 3 : 1 + i * 10]));
  const Events = pairs.slice(0, count).map(([b, type]) => [b * 2 + 1, type, scale[type] + Math.floor(rand() * (small ? 4 : 30))]);
  return [{ Events }];
}
